import{_ as a,o,c as r,ae as l}from"./chunks/framework.YL6nI5ZP.js";const p=JSON.parse('{"title":"Cómo Solucionar Problemas de Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/07-solucionar-problemas.md","filePath":"es/how-to/07-solucionar-problemas.md"}'),s={name:"es/how-to/07-solucionar-problemas.md"};function n(d,e,c,i,t,u){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="como-solucionar-problemas-de-local-swmm" tabindex="-1">Cómo Solucionar Problemas de Local SWMM <a class="header-anchor" href="#como-solucionar-problemas-de-local-swmm" aria-label="Permalink to &quot;Cómo Solucionar Problemas de Local SWMM&quot;">​</a></h1><p>Arregla problemas comunes con el mapa, las corridas, el build de WASM y la ruta WebGPU, y conoce las trampas conocidas de este codebase.</p><h2 id="como-arreglar-un-mapa-en-blanco-sin-teselas" tabindex="-1">Cómo arreglar un mapa en blanco / sin teselas <a class="header-anchor" href="#como-arreglar-un-mapa-en-blanco-sin-teselas" aria-label="Permalink to &quot;Cómo arreglar un mapa en blanco / sin teselas&quot;">​</a></h2><ul><li><code>public/config.js</code> falta o el token está vacío → créalo con un <code>MAPBOX_ACCESS_TOKEN</code> válido (consulta <a href="./02-configurar">Cómo Configurar Local SWMM</a>).</li><li>¿El navegador bloqueado por CSP? Revisa la consola en busca de violaciones de CSP contra <code>api.mapbox.com</code>.</li></ul><h2 id="como-arreglar-errores-de-run-inmediatos-con-una-advertencia" tabindex="-1">Cómo arreglar errores de &quot;Run&quot; inmediatos con una advertencia <a class="header-anchor" href="#como-arreglar-errores-de-run-inmediatos-con-una-advertencia" aria-label="Permalink to &quot;Cómo arreglar errores de &quot;Run&quot; inmediatos con una advertencia&quot;">​</a></h2><ul><li>Causa: sin nodos, sin outfall, o <strong>unidades US con una malla 2D</strong> (2D es solo SI) — <code>app.js:1402-1406</code>.</li><li>Fix: agrega al menos un nodo y un <code>OUTFALL</code>; cambia las unidades a SI si hay una malla 2D presente.</li></ul><h2 id="como-arreglar-una-corrida-que-falla-en-silencio-con-errores-del-motor" tabindex="-1">Cómo arreglar una corrida que falla en silencio / con errores del motor <a class="header-anchor" href="#como-arreglar-una-corrida-que-falla-en-silencio-con-errores-del-motor" aria-label="Permalink to &quot;Cómo arreglar una corrida que falla en silencio / con errores del motor&quot;">​</a></h2><ol><li>Revisa la ventana <strong>Run Status</strong> y luego la pestaña <strong>Report</strong>. Para diagnóstico profundo, el worker vuelca las líneas de error del <code>.rpt</code> y los primeros 3000 caracteres del INP al fallar (<code>openSwmm2dWorker.js:109-148</code>).</li><li>Reproduce en Node: <code>node scripts/run-engine-marcher.mjs model.inp out.json</code> imprime los códigos del motor (<code>SWMM_ERR_LIFECYCLE = 6</code> es el código de &quot;completado natural&quot;).</li></ol><h2 id="como-arreglar-un-build-de-wasm-que-falla-en-pluginfactory-cpp-46-unsupported-platform" tabindex="-1">Cómo arreglar un build de WASM que falla en <code>PluginFactory.cpp:46: unsupported platform</code> <a class="header-anchor" href="#como-arreglar-un-build-de-wasm-que-falla-en-pluginfactory-cpp-46-unsupported-platform" aria-label="Permalink to &quot;Cómo arreglar un build de WASM que falla en `PluginFactory.cpp:46: unsupported platform`&quot;">​</a></h2><ul><li>Causa: el submodule se re-fijó sin el commit de compatibilidad de wasm.</li><li>Fix: restaura <code>85e4be38</code> (consulta <a href="./03-compilar-desde-fuente">Cómo Compilar el Motor WASM desde el Código Fuente</a>, sección 5) o vuelve a aplicar los no-ops de Emscripten.</li></ul><h2 id="como-arreglar-could-not-find-zip-durante-el-bootstrap-de-vcpkg" tabindex="-1">Cómo arreglar <code>Could not find zip</code> durante el bootstrap de vcpkg <a class="header-anchor" href="#como-arreglar-could-not-find-zip-durante-el-bootstrap-de-vcpkg" aria-label="Permalink to &quot;Cómo arreglar `Could not find zip` durante el bootstrap de vcpkg&quot;">​</a></h2><ul><li>Causa: falta <code>zip</code>/<code>unzip</code>/<code>tar</code> del sistema.</li><li>Fix: en Arch: <code>sudo pacman -S zip unzip tar</code>.</li></ul><h2 id="como-manejar-una-corrida-2d-que-cae-de-vuelta-a-wasm" tabindex="-1">Cómo manejar una corrida 2D que cae de vuelta a WASM <a class="header-anchor" href="#como-manejar-una-corrida-2d-que-cae-de-vuelta-a-wasm" aria-label="Permalink to &quot;Cómo manejar una corrida 2D que cae de vuelta a WASM&quot;">​</a></h2><ul><li>Causa: <code>navigator.gpu</code> ausente o <code>maxStorageBuffersPerShaderStage &lt; 16</code> (p. ej., Apple Silicon/Metal).</li><li>Fix: no se necesita ninguno — esto es esperado; la ruta WASM es la referencia.</li></ul><h2 id="como-arreglar-fallas-de-generacion-de-malla-en-dominios-enormes" tabindex="-1">Cómo arreglar fallas de generación de malla en dominios enormes <a class="header-anchor" href="#como-arreglar-fallas-de-generacion-de-malla-en-dominios-enormes" aria-label="Permalink to &quot;Cómo arreglar fallas de generación de malla en dominios enormes&quot;">​</a></h2><ul><li>El heap de Triangle WASM está fijado en 16 MB; los límites de presupuesto (<code>trianglePointBudget=8000</code>, <code>autoAreaCap</code>) se activan automáticamente. Reduce el área del dominio o el minAngle.</li></ul><h2 id="como-arreglar-wasm-obsoleto-servido-en-cache" tabindex="-1">Cómo arreglar wasm obsoleto servido en caché <a class="header-anchor" href="#como-arreglar-wasm-obsoleto-servido-en-cache" aria-label="Permalink to &quot;Cómo arreglar wasm obsoleto servido en caché&quot;">​</a></h2><ul><li>El servidor envía <code>Cache-Control: no-store</code>, pero si estás alojando en otro lado, haz un refresh forzado después de recompilar (se usan parámetros de query <code>swmm6wasm.js?v=&lt;n&gt;</code> en <code>index.html:790-810</code>).</li></ul><h2 id="como-arreglar-fixtures-faltantes-para-los-scripts-de-webgpu" tabindex="-1">Cómo arreglar fixtures faltantes para los scripts de WebGPU <a class="header-anchor" href="#como-arreglar-fixtures-faltantes-para-los-scripts-de-webgpu" aria-label="Permalink to &quot;Cómo arreglar fixtures faltantes para los scripts de WebGPU&quot;">​</a></h2><ul><li>Regenera: <code>node scripts/make-marcher-inp.mjs …</code> / <code>node scripts/make-marcher-cpl-inp.mjs …</code> o ejecuta <code>verify-bellinge.mjs</code> una vez para poblar <code>scripts/verify-out/</code>.</li></ul><h2 id="trampas-y-rarezas-conocidas" tabindex="-1">Trampas y rarezas conocidas <a class="header-anchor" href="#trampas-y-rarezas-conocidas" aria-label="Permalink to &quot;Trampas y rarezas conocidas&quot;">​</a></h2><ol><li><strong>Deriva del README:</strong> el Inicio Rápido del README dice <code>cd SWMM_3D_Web_UI</code> y <code>http://localhost:8000</code>; el directorio real es <code>LocalSWMM</code> y el puerto es <code>8080</code>.</li><li><strong>Dos binarios de motor idénticos</strong> (<code>openswmm2d.*</code> y <code>swmm6wasm.*</code>) son copias byte por byte — mantenlos sincronizados (el script de build lo hace).</li><li><strong>Los mensajes de progreso de <code>simWorker</code> son protocolo muerto:</strong> el worker nunca los publica y <code>app.js:1275</code> los ignora; la barra de progreso 1D es cosmética basada en tiempo.</li><li><strong>El parseo de <code>.out</code> es solo 1D:</strong> la ruta 2D lleva arreglos JS por frame en su lugar y pone explícitamente <code>App.outData</code> en null (<code>app.js:1443</code>).</li><li><strong><code>bench-1d.mjs</code> lleva un comentario de cabecera &quot;probe-1d.mjs&quot; obsoleto.</strong></li><li><strong>Hard-coding solo de Windows</strong> en <code>bench-gpu-coupl.mjs</code> y <code>run-webgpu-harness.mjs</code> (ruta de Chrome hardcodeada).</li><li><strong>Los parámetros de la capa LID se parsean pero no se almacenan</strong> (<code>inpParser.js:411-424</code>) — los round-trips de LID dependen de <code>rawSections</code>.</li><li><strong>El <code>config.js</code> de CI usa <code>const CONFIG</code></strong> mientras que las configuraciones locales usan <code>var</code>; las búsquedas de <code>window.CONFIG</code> (<code>app.js:446</code>) son defensivas en cualquier caso.</li><li><strong>Las &quot;lecciones&quot; de <code>harness.html</code></strong> documentan una fijación histórica de VARIABLE_STEP que luego se demostró incorrecta — lee las entradas del 2026-08-06 en <code>WEBGPU_PLAN.md</code> antes de &quot;arreglar&quot; nada en <code>couplingSplit.js</code>.</li><li><strong>La reconstrucción de altura en vivo acoplada por vértices</strong> (<code>stCnt&gt;0</code>) existe en el kernel WGSL, pero el split limpia los punteros de stencil — la ruta en vivo usa la altura de la celda de lecho más baja.</li><li><strong>La precipitación NATURAL_NEIGHBOUR</strong> no la modela el marcher (solo media uniforme del gage).</li><li><strong>Capas del manifiesto de vcpkg:</strong> el <code>vcpkg.json</code> propio del motor se ignora para el build de wasm; solo se aplica el manifiesto raíz.</li></ol>',22)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
